<?php if ( ! defined( 'ABSPATH' ) ) { exit; } ?><section class="sd-dashboard-card"><div class="sd-card-heading"><h2><?php esc_html_e( 'Saved posts', 'social-discovery' ); ?></h2><a href="<?php echo esc_url( sd_home_url( 'workspace' ) . '#saved' ); ?>"><?php esc_html_e( 'View saved', 'social-discovery' ); ?></a></div><?php $ids = function_exists( 'sd_core_saved_activity_ids' ) ? array_slice( sd_core_saved_activity_ids(), 0, 3 ) : array(); if ( empty( $ids ) ) : ?><p class="sd-muted"><?php esc_html_e( 'You have no saved public posts yet.', 'social-discovery' ); ?></p><?php else : ?><ul class="sd-dashboard-list"><?php foreach ( $ids as $id ) : ?><li><a href="<?php echo esc_url( sd_home_url( 'feed' ) . '#activity-' . absint( $id ) ); ?>"><?php echo esc_html( sprintf( __( 'Saved activity #%d', 'social-discovery' ), absint( $id ) ) ); ?></a></li><?php endforeach; ?></ul><?php endif; ?></section>
